sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({
    api,
    event,
    helpers,
    imports
}) {
    if (api.state.selectedType == 'one') {
        api.setState('legal_entity_name', '');
        api.setState('registration_number', '');
        api.setState('domicile_country1', '');
        api.setState('authorized_reporter', '');
        api.setState('email_id1', '');
    } else if(api.state.selectedType == 'two'){
        api.setState('legal_name', '');
        api.setState('identity_verification_types', '');
        api.setState('domicile_country', '');
        api.setState('email_id', '');
    }

}
